import{_ as a,o as e,c as n,a3 as r}from"./chunks/framework.BlfGB29P.js";const b=JSON.parse('{"title":"富文本编辑与实时协同全景","description":"","frontmatter":{"title":"富文本编辑与实时协同全景","outline":[2,3]},"headers":[],"relativePath":"frontend/topics/editors-collaboration/index.md","filePath":"frontend/topics/editors-collaboration/index.md","lastUpdated":1785589115000}'),o={name:"frontend/topics/editors-collaboration/index.md"};function i(l,t,d,s,c,h){return e(),n("div",null,[...t[0]||(t[0]=[r(`<h1 id="富文本编辑与实时协同全景" tabindex="-1">富文本编辑与实时协同全景 <a class="header-anchor" href="#富文本编辑与实时协同全景" aria-label="Permalink to &quot;富文本编辑与实时协同全景&quot;">​</a></h1><blockquote><p>作者：codex-gpt-sol-5.6</p></blockquote><p>富文本编辑器不是一个加粗按钮加 <code>contenteditable</code>。浏览器负责输入法、选择区和 DOM 编辑，编辑器还要维护结构化文档、事务、历史、插件与渲染映射；多人协同时又增加并发收敛、断线恢复和在线状态。任一层边界不清，都会出现光标跳动、撤销破坏远端内容或粘贴不可信 HTML 等问题。</p><p>本分组以“结构化文档编辑器”为边界，建立从单机输入到实时协同的完整知识地图。具体产品可采用 ProseMirror、Lexical、Slate、Tiptap 或自研内核，但底层问题不会因为框架不同而消失。</p><h2 id="_1-系统分层" tabindex="-1">1. 系统分层 <a class="header-anchor" href="#_1-系统分层" aria-label="Permalink to &quot;1. 系统分层&quot;">​</a></h2><h3 id="_1-1-输入与浏览器适配" tabindex="-1">1.1 输入与浏览器适配 <a class="header-anchor" href="#_1-1-输入与浏览器适配" aria-label="Permalink to &quot;1.1 输入与浏览器适配&quot;">​</a></h3><p>浏览器层提供 <code>contenteditable</code>、<code>beforeinput</code>、CompositionEvent、Selection、Range、ClipboardEvent 与 DragEvent。适配层把这些不稳定的 DOM 事件翻译成编辑器命令，不把 DOM 当作唯一文档数据源。</p><h3 id="_1-2-文档内核" tabindex="-1">1.2 文档内核 <a class="header-anchor" href="#_1-2-文档内核" aria-label="Permalink to &quot;1.2 文档内核&quot;">​</a></h3><p>文档内核通常包含：</p><ul><li>Schema：允许哪些节点、标记和属性；</li><li>Document：当前不可变或受控可变的文档状态；</li><li>Selection：文本、节点或自定义选择；</li><li>Operation / Step：最小变更及其映射；</li><li>Transaction：一组原子变更及元数据；</li><li>History：可撤销的本地意图；</li><li>Plugin State：由事务驱动的扩展状态。</li></ul><h3 id="_1-3-协同与服务端" tabindex="-1">1.3 协同与服务端 <a class="header-anchor" href="#_1-3-协同与服务端" aria-label="Permalink to &quot;1.3 协同与服务端&quot;">​</a></h3><p>协同层传播操作或 CRDT 更新，维护版本、确认、重试、快照和权限。Presence 只描述光标、选区和在线状态，通常是可丢失的临时数据，不应与必须持久化的文档更新共用一致性语义。</p><h2 id="_2-文章索引" tabindex="-1">2. 文章索引 <a class="header-anchor" href="#_2-文章索引" aria-label="Permalink to &quot;2. 文章索引&quot;">​</a></h2><h3 id="_2-1-浏览器输入层" tabindex="-1">2.1 浏览器输入层 <a class="header-anchor" href="#_2-1-浏览器输入层" aria-label="Permalink to &quot;2.1 浏览器输入层&quot;">​</a></h3><table tabindex="0"><thead><tr><th>文章</th><th>负责的问题</th></tr></thead><tbody><tr><td><a href="/frontend/topics/editors-collaboration/contenteditable-selection-range">contenteditable、Selection 与 Range</a></td><td>编辑宿主、DOM 选择区、边界点与模型位置映射</td></tr><tr><td><a href="/frontend/topics/editors-collaboration/input-ime-clipboard-dnd">输入事件、IME、剪贴板与拖放</a></td><td>输入事件顺序、组合输入、粘贴清洗和拖放数据</td></tr></tbody></table><h3 id="_2-2-编辑器内核" tabindex="-1">2.2 编辑器内核 <a class="header-anchor" href="#_2-2-编辑器内核" aria-label="Permalink to &quot;2.2 编辑器内核&quot;">​</a></h3><table tabindex="0"><thead><tr><th>文章</th><th>负责的问题</th></tr></thead><tbody><tr><td><a href="/frontend/topics/editors-collaboration/document-model-rendering">文档模型、事务与渲染</a></td><td>Schema、节点、位置、Operation、Transaction 和增量渲染</td></tr><tr><td><a href="/frontend/topics/editors-collaboration/commands-history">命令、历史记录与撤销重做</a></td><td>命令可用性、逆操作、分组、选择恢复和协同历史边界</td></tr><tr><td><a href="/frontend/topics/editors-collaboration/plugin-system">插件与扩展机制</a></td><td>插件状态、命令、快捷键、装饰、节点视图和生命周期</td></tr></tbody></table><h3 id="_2-3-实时协同" tabindex="-1">2.3 实时协同 <a class="header-anchor" href="#_2-3-实时协同" aria-label="Permalink to &quot;2.3 实时协同&quot;">​</a></h3><table tabindex="0"><thead><tr><th>文章</th><th>负责的问题</th></tr></thead><tbody><tr><td><a href="/frontend/topics/editors-collaboration/ot-crdt">OT、CRDT 与并发收敛</a></td><td>并发操作如何转换或合并，以及两类算法的代价</td></tr><tr><td><a href="/frontend/topics/editors-collaboration/protocol-presence">协同协议、同步与在线状态</a></td><td>Snapshot、Update、Ack、重连、幂等、权限和 Presence</td></tr></tbody></table><h3 id="_2-4-生产质量" tabindex="-1">2.4 生产质量 <a class="header-anchor" href="#_2-4-生产质量" aria-label="Permalink to &quot;2.4 生产质量&quot;">​</a></h3><table tabindex="0"><thead><tr><th>文章</th><th>负责的问题</th></tr></thead><tbody><tr><td><a href="/frontend/topics/editors-collaboration/performance-testing-security">编辑器性能、测试、可访问性与安全</a></td><td>大文档、输入延迟、组合测试、键盘读屏、HTML 清洗和监控</td></tr></tbody></table><h2 id="_3-一次输入的结果流" tabindex="-1">3. 一次输入的结果流 <a class="header-anchor" href="#_3-一次输入的结果流" aria-label="Permalink to &quot;3. 一次输入的结果流&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>键盘 / IME / 粘贴</span></span>
<span class="line"><span>  -&gt; beforeinput / composition / clipboard</span></span>
<span class="line"><span>  -&gt; 浏览器适配层解析意图</span></span>
<span class="line"><span>  -&gt; command 判断是否可执行</span></span>
<span class="line"><span>  -&gt; transaction 修改 document + selection</span></span>
<span class="line"><span>  -&gt; plugin state 随事务更新</span></span>
<span class="line"><span>  -&gt; view 增量渲染并恢复 DOM selection</span></span>
<span class="line"><span>  -&gt; history 记录本地意图</span></span>
<span class="line"><span>  -&gt; collaboration 编码并发送更新</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br></div></div><p>浏览器可能先修改 DOM，也可能允许应用在 <code>beforeinput</code> 中阻止默认行为。成熟编辑器需要 DOM Observer 和输入适配共同工作，不能假定所有浏览器、输入法和元素类型都产生完全一致的事件序列。</p><h2 id="_4-技术选型边界" tabindex="-1">4. 技术选型边界 <a class="header-anchor" href="#_4-技术选型边界" aria-label="Permalink to &quot;4. 技术选型边界&quot;">​</a></h2><table tabindex="0"><thead><tr><th>场景</th><th>更合理的起点</th></tr></thead><tbody><tr><td>少量普通文本和格式</td><td>原生表单、Markdown 编辑器或轻量 <code>contenteditable</code> 封装</td></tr><tr><td>结构化块、插件、复杂选择</td><td>成熟编辑器内核</td></tr><tr><td>Google Docs 类分页与精细排版</td><td>专用布局与渲染系统，成本显著高于普通富文本</td></tr><tr><td>多人文档</td><td>支持 OT/CRDT 的成熟协同栈，或明确服务端版本协议</td></tr><tr><td>代码编辑器</td><td>Monaco、CodeMirror 等专用文本编辑器，不与富文本内核混用</td></tr></tbody></table><p>采用成熟内核仍要掌握本文的模型，因为 Schema 迁移、插件冲突、输入法故障、协同恢复和安全策略最终都由业务负责。</p><h2 id="_5-推荐学习顺序" tabindex="-1">5. 推荐学习顺序 <a class="header-anchor" href="#_5-推荐学习顺序" aria-label="Permalink to &quot;5. 推荐学习顺序&quot;">​</a></h2><ol><li>先理解 <code>contenteditable</code>、Selection、Range 和输入事件。</li><li>再建立 Document、Selection、Operation 与 Transaction 模型。</li><li>掌握命令、历史和插件的单机生命周期。</li><li>理解 OT / CRDT 的收敛目标，再设计网络同步协议。</li><li>最后用输入法、弱网、大文档、键盘和恶意粘贴做生产验收。</li></ol><h2 id="_6-掌握标准" tabindex="-1">6. 掌握标准 <a class="header-anchor" href="#_6-掌握标准" aria-label="Permalink to &quot;6. 掌握标准&quot;">​</a></h2><ul><li>能解释 DOM 选择区与模型选择区为什么不能直接等同。</li><li>能把一次输入表示为可验证事务，而不是任意 DOM 修改。</li><li>能实现不会破坏外部修改的撤销，并说明历史分组规则。</li><li>能说明 OT 与 CRDT 的收敛条件、元数据和服务端职责。</li><li>能处理重连、重复消息、权限变化和 Schema 版本不兼容。</li><li>能用真实 IME、粘贴、拖放、读屏和大文档场景验收编辑器。</li></ul><h2 id="_7-参考资料" tabindex="-1">7. 参考资料 <a class="header-anchor" href="#_7-参考资料" aria-label="Permalink to &quot;7. 参考资料&quot;">​</a></h2><ul><li><a href="https://w3c.github.io/editing/docs/" target="_blank" rel="noreferrer">W3C Editing APIs</a></li><li><a href="https://www.w3.org/TR/input-events-2/" target="_blank" rel="noreferrer">Input Events Level 2</a></li><li><a href="https://prosemirror.net/docs/guide/" target="_blank" rel="noreferrer">ProseMirror Guide</a></li><li><a href="https://docs.yjs.dev/" target="_blank" rel="noreferrer">Yjs Documentation</a></li></ul>`,33)])])}const u=a(o,[["render",i]]);export{b as __pageData,u as default};
